input.command:
cd <out>/h15-everwrite-2
mkdir scripts && cp ../plugin-everwrite/skills/everwrite/scripts/tells.py scripts/tells.py
cat > scripts/lint-prose.js <<'EOF'
// Runs the prose checker (scripts/tells.py) over README.md and the English docs.
// Two-letter folders under docs/ (de, fr, ...) are skipped: the checker only
// knows English, and its dash rule would flag normal German and French typography.
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

function collect(dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!/^[a-z]{2}$/.test(entry.name)) out.push(...collect(full));
    } else if (entry.name.endsWith('.md')) {
      out.push(full);
    }
  }
  return out;
}

const files = ['README.md', ...collect('docs').sort()];
const script = path.join(__dirname, 'tells.py');
for (const py of ['python3', 'python']) {
  const r = spawnSync(py, [script, ...files], { stdio: 'inherit' });
  if (r.error && r.error.code === 'ENOENT') continue;
  process.exit(r.status ?? 1);
}
console.error('lint:prose needs Python 3.9 or later on the PATH');
process.exit(1);
EOF
python3 - <<'EOF'
import re
p='package.json'; s=open(p).read()
s=s.replace('"test": "node -e \\"console.log(\'tests ok\')\\""','"test": "node -e \\"console.log(\'tests ok\')\\"",\n    "lint:prose": "node scripts/lint-prose.js"')
open(p,'w').write(s)
p='README.md'; s=open(p).read()
s=s.replace('> "Let me know','<!-- tells: off -->\n> "Let me know').replace('Delete it.\n','Delete it.\n<!-- tells: on -->\n',1)
open(p,'w').write(s)
p='.github/workflows/ci.yml'; s=open(p).read()
s+='''  prose:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - run: npm run lint:prose
'''
open(p,'w').write(s)
EOF
cat package.json; sed -n 5,12p README.md; npm run lint:prose; echo exit=$?
mv docs/guide.md /tmp/g.md; npm run lint:prose | tail -3; echo exit=$?; mv /tmp/g.md docs/guide.md
echo "Let me know if this helps — it is robust." > docs/new.md; npm run lint:prose >/dev/null; echo new-bad exit=$?; rm docs/new.md

